<script setup lang="ts">
import { onMounted, ref } from "vue"; import { api } from "../api"; import { Brain, Pencil, Trash2 } from "lucide-vue-next";
type Fact={id:string;attribute:string;value:string;createdAt:string;supersededById?:string;userEdited:boolean}; type Entity={id:string;type:string;canonicalName:string;facts:Fact[]}; const memories=ref<Entity[]>([]);
async function load(){memories.value=await api("/memories");} async function edit(f:Fact){const value=prompt("修改记忆",f.value);if(value&&value!==f.value){await api(`/memories/facts/${f.id}`,{method:"PATCH",body:JSON.stringify({value})});await load();}} async function remove(id:string){if(confirm("确认删除该实体的全部记忆和历史版本？")){await api(`/memories/${id}`,{method:"DELETE"});await load();}} onMounted(load);
</script>
<template><div class="page"><header class="page-header"><div><h1>记忆管理</h1><p>系统自动提取的人物、时间、地点、主题与关系</p></div></header><div v-if="!memories.length" class="big-empty"><Brain/><h3>还没有长期记忆</h3><p>完成对话或会议分析后，相关事实会在后台自动整理。</p></div><div class="memory-grid"><article v-for="entity in memories" :key="entity.id" class="memory-card"><header><span class="badge">{{entity.type}}</span><strong>{{entity.canonicalName}}</strong><button class="icon danger" title="删除记忆" @click="remove(entity.id)"><Trash2 :size="16"/></button></header><div v-for="fact in entity.facts" :key="fact.id" :class="['fact',{old:fact.supersededById}]"><div><small>{{fact.attribute}}</small><p>{{fact.value}}</p></div><button v-if="!fact.supersededById" class="icon" title="编辑记忆" @click="edit(fact)"><Pencil :size="15"/></button></div></article></div></div></template>
